const body = $json.body || $json || {};

const action = String(body.action || '').trim();

return [
  {
    json: {
      action,
      requested_by: body.requested_by || '',
      requested_by_name: body.requested_by_name || '',

      ingreso: body.ingreso || {},
    },
  },
];

const rows = $input.all();

function toNumber(value) {
  const clean = String(value || '')
    .replace(/Bs\.?/gi, '')
    .replace(/\s/g, '')
    .replace(/,/g, '');

  const num = Number(clean);
  return Number.isFinite(num) ? num : 0;
}

const facturas = rows
  .map((item) => item.json)
  .filter((row) => row.invoice_uid)
  .filter((row) => row.estado_ingreso === 'Cuenta por cobrar')
  .map((row) => ({
    invoice_uid: row.invoice_uid || '',
    nro_factura: row.nro_factura || '',
    cliente_nombre: row.cliente_nombre || '',
    cliente_nit_ci: row.cliente_nit_ci || '',
    fecha_emision: row.fecha_emision || '',
    fecha_iso: row.fecha_iso || '',
    fecha_estimada_ingreso: row.fecha_estimada_ingreso || '',
    fecha_ingreso_real: row.fecha_ingreso_real || '',
    monto_pagar: toNumber(row.monto_pagar || row.total),
    total: toNumber(row.total),
    metodo_pago: row.metodo_pago || '',
    estado_ingreso: row.estado_ingreso || '',
    nivel: row.nivel || '',
    uploaded_by: row.uploaded_by || '',
    uploaded_by_name: row.uploaded_by_name || '',
    filename_original: row.filename_original || '',
  }));

return [
  {
    json: {
      ok: true,
      message: 'Cuentas por cobrar obtenidas correctamente.',
      facturas,
    },
  },
];

const payload = $('Code - Normalize Action').first().json.ingreso || {};
const rows = $input.all();

const found = rows
  .map((item) => item.json)
  .find((row) => row && row.invoice_uid);

if (!found) {
  return [
    {
      json: {
        ok: false,
        not_found: true,
        message: 'No se encontró la factura para actualizar.',
        invoice_uid: payload.invoice_uid || '',
      },
    },
  ];
}

const invoice_uid = String(payload.invoice_uid || '').trim();
const fecha_ingreso_real = String(payload.fecha_ingreso_real || '').trim();

if (!invoice_uid) {
  throw new Error('invoice_uid es obligatorio');
}

if (!fecha_ingreso_real) {
  throw new Error('fecha_ingreso_real es obligatoria');
}

const updated_at = payload.updated_at || new Date().toISOString();

return [
  {
    json: {
      ok: true,

      row_number: found.row_number || found.rowNumber || found.__rowNumber || '',

      invoice_uid,
      nro_factura: found.nro_factura || '',
      cliente_nombre: found.cliente_nombre || '',
      monto_pagar: found.monto_pagar || found.total || '',

      estado_anterior: found.estado_ingreso || '',
      estado_nuevo: 'Ya ingresado',

      fecha_estimada_ingreso_anterior: found.fecha_estimada_ingreso || '',
      fecha_estimada_ingreso_nueva: found.fecha_estimada_ingreso || '',

      estado_ingreso: 'Ya ingresado',
      fecha_ingreso_real,

      observacion: payload.observacion || '',

      updated_by: payload.updated_by || '',
      updated_by_name: payload.updated_by_name || '',
      updated_at,
    },
  },
];

