return rows.map((row) => ({
  json: {
    ...row,
    row_number: row.row_number || row.rowNumber || row.__rowNumber || '',
    estado_ingreso: 'Ya ingresado',
    fecha_ingreso_real: update.fecha_ingreso_real,
    fecha_estimada_ingreso: update.fecha_estimada_ingreso_nueva || '',
  },
}));

